      { auteur: "Ibn Rushd", avis: "C'est tenu pour pur ; demander est recommandé ; s'ils disent impur, il les croit ; ce qui vient des chrétiens est tenu pour impur.", statut: "non_precise" },
      { auteur: "Aḥmad az-Zarqānī (rapporté par al-Bunānī, chez al-Dasūqī)", avis: "C'est une vraie tolérance : l'eau des auvents est le plus souvent impure.", statut: "qawl" }
