      { auteur: "Certains (rapportés par at-Tawḍīḥ)", avis: "La tolérance est limitée au sang versé licitement ; pas au sang d'une agression.", statut: "non_precise" },
      { auteur: "Ibn al-ʿArabī (d'après Ibn ʿArafa)", avis: "Essuyer l'objet poli suffit, sans restreindre la règle au sang.", statut: "non_precise" }
